import pandas as pd, numpy as np
from scipy import stats

for i in [1,2,3,7,8,9,11,13]:
    df = pd.read_csv(eval(f"experiment_{i}_csv"))
    print(f"--- exp {i} cols={list(df.columns)} n={len(df)}")
    if 'CropYield' in df.columns:
        for c in df.columns:
            if c not in ('unit_id','CropYield') and df[c].dtype!=object:
                try:
                    r,p = stats.pearsonr(df[c], df['CropYield'])
                    print(f"   {c}: r={r:.3f} p={p:.2g} mean={df[c].mean():.2f}")
                except Exception as e:
                    print(c, e)
        print("   Yield mean=",round(df['CropYield'].mean(),2))

